import type { Option, Paper, Paragraph, Passage } from '@/types/paper';

/**
 * 2025 年 6 月大学英语六级真题（第 1–3 套）站内作答数据。
 * 检索日期：2026-11-19。
 * 来源与核验：
 * - 题面 / 选项 / 答案 / 选词填空词库 / 长篇阅读段落 / 写作范文 / 翻译参考译文：
 *   过级鸭 guojiya.cn/exam/cet6_2025_06_N/answers（整卷结构化页面，2026-11-19 逐套抓取）。
 * - 听力原文：词通英语 wordcram.com.cn/tests/cet6/listening/2025-06-N（精听页逐句英文 + 中文对照）。
 * - 答案以过级鸭所载答案表为准，选词填空 26–35、长篇阅读 36–45 的答案取自其「答案与解析」区。
 * - 听力部分给出原文，由站内合成朗读（非考试原音）；官方从不发布历年真题与听力音频。
 * - 写作范文与翻译参考译文均为机构参考版本，非唯一正确写法。
 */

/** 长篇阅读选项：由各段落生成（key=段落标记，text=段落首句，超过 60 字符截断） */
function matchOptions(paras: Paragraph[]): Option[] {
  return paras
    .filter((p): p is Paragraph & { marker: string } => Boolean(p.marker))
    .map((p) => {
      const dot = p.text.indexOf('. ');
      const first = dot > 0 ? p.text.slice(0, dot + 1) : p.text;
      const text = first.length > 60 ? `${first.slice(0, 60).replace(/[\s,;:]+$/, '')}…` : first;
      return { key: p.marker, text: `${p.marker}) ${text}` };
    });
}

/** cet6-2025-06-s1 长篇阅读段落 */
const mp_cet6_2025_06_s1: Passage = {
  id: 'cet6-2025-06-s1-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2025-06-s1-mp-A', marker: 'A', text: `Librarians know the value of their community services, and their patrons appreciate their importance as well. But in an increasingly digital world, we see the role of libraries as community and cultural centers at times undervalued. When shrinking municipal budgets combine with the nonstop technological revolution, public library services that focus on building communities face-to-face, inspiring and educating patrons about art, literature, and music, and helping patrons engage in civil discourse can seem old-fashioned. But it is precisely those shrinking budgets and the assault of technologically mediated life that make public libraries' cultural and community offerings more important than ever.` },
    { id: 'cet6-2025-06-s1-mp-B', marker: 'B', text: `Many people point out the value public libraries bring to their communities. More than just books and banks of computers, libraries are still places where individuals gather to explore, interact, and imagine. Some of the specific ways in which libraries add value to our communities and serve as cultural centers for our patrons are community builders, centers for the arts, and champions of youth. Libraries serve in these capacities and are more than just about information.` },
    { id: 'cet6-2025-06-s1-mp-C', marker: 'C', text: `As community builders, libraries are engaged in incredible work. From tiny public libraries to huge city institutions with multiple branches, libraries across the United States are building community and supporting local culture in exciting ways. These are inspiring and hopefully will encourage librarians interested in community services and cultural outreach to make connections with each other, share ideas, and build partnerships. Supporters of libraries as community builders claim that unless you are out there changing neighborhoods, you are not completing the work you are to do. Strengthening neighborhoods and championing the cultural lives of communities are big responsibilities.` },
    { id: 'cet6-2025-06-s1-mp-D', marker: 'D', text: `Place-based economic development stresses the importance of offering attractive, functional, and community-based places, such as libraries, in town squares and depressed neighborhoods. Like a major department store in a mall, libraries attract large numbers of people, creating economic opportunities for numerous businesses and organizations in the surrounding area. Large cities, medium-sized ones, and even small towns have successfully transformed their libraries into the hubs (枢纽) of vibrant neighborhoods.` },
    { id: 'cet6-2025-06-s1-mp-E', marker: 'E', text: `As key municipal agencies, and focal points for community education, libraries are major players in creating livable, environmentally friendly cities and towns. The Urban Libraries Council released a report detailing the unique ways in which libraries can further sustainability at the local level. Beyond ensuring that library construction projects consider environmental impact, libraries can take a lead in supporting local foods and craftsmen—like the Peabody Institute Library's partnering with local businesses to pioneer a farmers' market in their courtyard, or the Richmond Public Library's seed lending library which "nurtures locally-adapted plant varieties, and fosters community resilience (韧性), self-reliance and a culture of sharing."` },
    { id: 'cet6-2025-06-s1-mp-F', marker: 'F', text: `Archives preserve historic artifacts, oral histories, digital history projects, and scholarly writings relevant to the community, including minority groups. Communities lucky enough to have archivists have a great advantage when it comes to organizing historical records and artifacts. An organized archive is a place where people can research their ancestry and immigration history, do environmental research, and more. An archivist is an advocate for preservation who, among other things, coordinates the restoration of maps and paintings, the digitization of vital records, and the creation of oral history projects. With projects like the Massachusetts Memories Road Show and the Veterans History Project, evidence of the importance of archives is everywhere.` },
    { id: 'cet6-2025-06-s1-mp-G', marker: 'G', text: `In the words of Robert Putnam, "People may go to the library looking mainly for information, but they find each other there." New moms connect at baby story-times; elderly people, often facing difficult life transitions, attend events and find that they make new friends; teenagers meet up in libraries' teen spaces after school; and readers discuss current events in the periodicals room. In libraries, community-building connections are happening all the time.` },
    { id: 'cet6-2025-06-s1-mp-H', marker: 'H', text: `As Keith Richards said, "The public library is the great equalizer." Despite the rising costs of concert and theater tickets, public library events (including concerts, author visits, and gallery displays) are often offered free of charge, enabling people of any income level to attend. In addition, library book groups allow people to explore and discuss the literary arts, and the Great Stories Club introduces at-risk youth to literature. The best part: it's all free and open to the public.` },
    { id: 'cet6-2025-06-s1-mp-I', marker: 'I', text: `In a time when education is increasingly expensive, public libraries provide information and educational opportunities free for all people, regardless of their socio-economic status. Offered by libraries across the country, American Library Association's Let's Talk about It programs are wonderful examples of scholar-facilitated learning opportunities in libraries. In addition, many libraries present classes and discussion programs, and some even provide online continuing education courses such as the Universal Class database.` },
    { id: 'cet6-2025-06-s1-mp-J', marker: 'J', text: `Librarians know that patrons aren't just information consumers, they're information producers. Patrons use the library to gain knowledge in order to create their own new and independent works. Increasing numbers of libraries provide spaces and services that meet the needs of people who want to learn how to edit Wikipedia, set up blogs or podcasts, create their own magazines, and so much more. Many libraries offer art or writing workshops and groups, and some provide music practice rooms for patrons. Programs like ImaginOn in Charlotte, North Carolina, provide exciting models that take community partnership, creativity, and creation to a new level.` },
    { id: 'cet6-2025-06-s1-mp-K', marker: 'K', text: `The decline of civil discourse stems in part from the fact that it is so easy for people to watch news about, buy products from, and engage in both the virtual and real worlds—only with those of similar backgrounds and ideologies. Public libraries, through such programs as The Human Library and Socrates Cafe, can help build small communities of difference that encourage people to interact with and learn from each other through dialogue. By both actively promoting civil discourse through these programs, and modeling and upholding the principles of free inquiry and expression for all, libraries help individuals rediscover the importance of an increased need for civil discourse in American life.` },
    { id: 'cet6-2025-06-s1-mp-L', marker: 'L', text: `Free tutoring, homework help programs, and summer reading programs for kids and teens help bridge the economic divide that impacts students' academic performance. The cost of hiring a private tutor is well beyond what many library patrons can afford, so libraries offer homework help and tutoring online, by phone, in person, and even through social media and homework apps. Annual summer reading programs also have a positive impact on student performance and, according to a 2010 study conducted by Dominican University's Graduate School of Library and Information Science, students' reading skills get a boost from these popular nationwide events.` },
    { id: 'cet6-2025-06-s1-mp-M', marker: 'M', text: `Through library collections, programs, and physical spaces, children learn to share, to be engaged in their communities, to participate in the arts, and to explore their immediate world and the world at large. There are surely endless examples of innovative library services for children, including the Middle Country Public Library's Nature Explorium, which engages children in learning about the natural world.` },
    { id: 'cet6-2025-06-s1-mp-N', marker: 'N', text: `These examples are just a few of the many amazing things that public libraries around the United States (and the world) are doing to build and maintain strong community connections. We encourage you to try some of these ideas in your own libraries, and we hope that these ideas will help you be better able to convince your community leaders of the important role that public libraries play in communities large and small.` },
  ],
};
/** cet6-2025-06-s2 长篇阅读段落 */
const mp_cet6_2025_06_s2: Passage = {
  id: 'cet6-2025-06-s2-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2025-06-s2-mp-A', marker: 'A', text: `I can be a reluctant socialiser. I'm sometimes secretly pleased when social plans are called off. I get restless a few hours into a hangout. I even once went on a free 10-day silent meditation (冥想) retreat - not for the meditation, but for the silence.` },
    { id: 'cet6-2025-06-s2-mp-B', marker: 'B', text: `So I can relate to author Anneli Rufus, who wrote in Party of One: The Loners' Manifesto: "When parents on TV shows punished their kids by ordering them to go to their rooms, I was confused. I loved my room. Being there behind a locked door was a treat. To me a punishment was being ordered to play games with my cousin Louis."` },
    { id: 'cet6-2025-06-s2-mp-C', marker: 'C', text: `Unsocial tendencies like these are often far from ideal. Abundant research shows the harms of social isolation, considered a serious public health problem in countries that have rapidly ageing populations (though talk of a "loneliness epidemic" may be exaggerated). In the UK, the Royal College of General Practitioners says that loneliness has the same risk level for premature death as diabetes. Strong social connections are important for cognitive functioning, motor function and a smoothly running immune system.` },
    { id: 'cet6-2025-06-s2-mp-D', marker: 'D', text: `This is especially clear from cases of extreme social isolation. Examples of people kept in captivity, children kept isolated in abusive orphanages, and prisoners kept in solitary confinement all show how prolonged solitude can lead to hallucinations (幻觉) and other forms of mental instability.` },
    { id: 'cet6-2025-06-s2-mp-E', marker: 'E', text: `But these are severe and involuntary cases of aloneness. For those of us who just prefer plenty of alone time, emerging research suggests some good news: there are upsides to being alone - for both our work lives and our emotional well-being.` },
    { id: 'cet6-2025-06-s2-mp-F', marker: 'F', text: `Solitude is a time for reflection, for thinking about things more deeply. In a world increasingly focused on speed and competitiveness, solitude is precious and something to be treasured. And there are benefits in learning to love your solitude.` },
    { id: 'cet6-2025-06-s2-mp-G', marker: 'G', text: `One key benefit of solitude is improved creativity. Gregory Feist, who focuses on the psychology of creativity at California's San Jose State University, has defined creativity as thinking or activity with two key elements: originality and usefulness. He has found that personality traits commonly associated with creativity are openness (receptiveness to new thoughts and experiences), self-confidence, and autonomy - which may include "a lack of concern for social norms" and "a preference for being alone". In fact, Feist's research on both artists and scientists shows that one of the most prominent features of creative folks is their lesser interest in socialising.` },
    { id: 'cet6-2025-06-s2-mp-H', marker: 'H', text: `One reason for this is that such people are likely to spend sustained time alone working on their craft. Plus, Feist says, many artists "are trying to make sense of their internal world and a lot of internal personal experiences that they're trying to give expression and meaning to through their art." Solitude allows for the reflection and observation necessary for that creative process.` },
    { id: 'cet6-2025-06-s2-mp-I', marker: 'I', text: `A recent justification of these ideas came from University at Buffalo psychologist Julie Bowker, who researches social withdrawal. Social withdrawal is usually categorised into three types: shyness caused by fear or anxiety; avoidance, from a dislike of socialising; and unsociability, from a preference for solitude. A paper by Bowker and her colleagues was the first to show that a type of social withdrawal could have a positive effect - they found that creativity was linked specifically to unsociability. They also found that unsociability had no correlation with aggression (shyness and avoidance did). This was significant because while previous research had suggested that unsociability might be harmless, Bowker and colleagues' paper showed that it could actually be beneficial. Unsociable people are likely to be "having just enough interaction," Bowker says. "They have a preference for being alone, but they also don't mind being with others."` },
    { id: 'cet6-2025-06-s2-mp-J', marker: 'J', text: `Still, it turns out that solitude is important for more than creativity. It's commonly believed that leaders need to be sociable. But this depends, among other things, on the personalities of their employees. One 2011 study showed that in branches of a pizza chain where employees were more passive, outgoing bosses were associated with higher profits. But in branches where employees were more active, introverted (内向的) leaders were more effective. One reason for this is that introverted people are less likely to feel threatened by strong personalities and suggestions. They're also more likely to listen.` },
    { id: 'cet6-2025-06-s2-mp-K', marker: 'K', text: `Since ancient times, meanwhile, people have been aware of a link between isolation and mental focus. After all, cultures with traditions of religious hermits (隐士) believe that solitude is important for enlightenment. Recent research has given us a better understanding of why. One benefit of unsociability is the brain's state of active mental rest, which goes hand-in-hand with the stillness of being alone. When another person is present, your brain can't help but pay some attention. This can be a positive distraction. But it's still a distraction.` },
    { id: 'cet6-2025-06-s2-mp-L', marker: 'L', text: `Daydreaming in the absence of such distractions activates the brain's default-mode network. Among other functions, this network helps to consolidate memory and understand others' emotions. Giving free rein to a wandering mind not only helps with focus in the long term but strengthens your sense of both yourself and others. Paradoxically, therefore, periods of solitude actually help when it comes time to socialise once more. And the occasional absence of focus ultimately helps concentration in the long run.` },
    { id: 'cet6-2025-06-s2-mp-M', marker: 'M', text: `A more recent advocate of thoughtful and productive solitude is Susan Cain, author of Quiet: The Power of Introverts in a World That Can't Stop Talking and founder of Quiet Revolution, a company that promotes quiet and introvert-friendly workplaces. "These days, we tend to believe that creativity emerges from a decidedly unreserved socialising process, but in fact it requires sustained attention and deep focus," she says. "Also, humans are such absorbent social beings that when we surround ourselves with others, we automatically take in their opinions and aesthetics. To truly chart our own path or vision, we have to be willing to isolate ourselves, at least for some period of time."` },
    { id: 'cet6-2025-06-s2-mp-N', marker: 'N', text: `Still, the line between useful solitude and dangerous isolation can be blurry. "Almost anything can be adaptive and maladaptive, depending on how extreme they get," Feist says. A disorder has to do with dysfunction. If someone stops caring about people and cuts off all contact, this could point to an irrational neglect of social relations. But creative unsociability is a far cry from this. In fact, Feist says, "there's a real danger with people who are never alone. It's hard to examine one's own thoughts, feelings and motives, to be self-aware, and fully relaxed unless you have occasional solitude. In addition, introverts tend to have fewer but stronger friendships - which has been linked to greater happiness."` },
    { id: 'cet6-2025-06-s2-mp-O', marker: 'O', text: `As with many things, quality reigns over quantity. Nurturing a few solid relationships without feeling the need to constantly populate your life with endless chatting ultimately may be better for you.` },
    { id: 'cet6-2025-06-s2-mp-P', marker: 'P', text: `Thus, if your personality tends toward unsociability, you shouldn't feel the need to change. Of course, that comes with qualifications. But as long as you have regular social contact, you are choosing solitude rather than being forced into it, you have at least a few good friends and your solitude is good for your well-being or productivity, there's no point agonising over how to fit a square personality into a round hole.` },
  ],
};
/** cet6-2025-06-s3 长篇阅读段落 */
const mp_cet6_2025_06_s3: Passage = {
  id: 'cet6-2025-06-s3-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2025-06-s3-mp-A', marker: 'A', text: `As the scale and impacts of climate change become increasingly alarming, meat is a popular target for action. Advocates for the protection of the natural environment from destruction or pollution urge the public to eat less meat. Some activists have even called for taxing meat to reduce consumption of it.` },
    { id: 'cet6-2025-06-s3-mp-B', marker: 'B', text: `A key claim underlying these arguments holds that globally, meat production generates more greenhouse gases than the entire transportation sector. However, this claim is demonstrably wrong, as I will show. And its persistence has led to false assumptions about the linkage between meat and climate change.` },
    { id: 'cet6-2025-06-s3-mp-C', marker: 'C', text: `My recent research focuses on ways in which animal agriculture affects air quality and climate change. In my view, there are many reasons for either choosing animal protein or opting for a vegetarian selection. However, abandoning meat and meat products is not the environmental panacea (万灵药) many would have us believe. And if taken to an extreme, it also could have harmful nutritional consequences.` },
    { id: 'cet6-2025-06-s3-mp-D', marker: 'D', text: `A healthy portion of meat's negative reputation centers on the assertion that livestock is the largest source of greenhouse gases worldwide. For example, an analysis published in 2009 by the World Watch Institute based in Washington, D.C. asserted that 51 percent of global greenhouse gas emissions come from rearing and processing livestock. According to the U.S. Environmental Protection Agency, the largest sources of U.S. greenhouse gas emissions in 2016 were electricity production (28 percent of total emissions), transportation (28 percent) and industry (22 percent). All of agriculture accounted for a total of 9 percent, but all of animal agriculture contributes less than half of this amount, representing 3.9 percent of the total greenhouse emission in the U.S. That is very different from claiming that livestock represents as much as or more than transportation.` },
    { id: 'cet6-2025-06-s3-mp-E', marker: 'E', text: `Why is there such a misconception? In 2006 the United Nations Food and Agriculture Organization (FAO) published a study titled "Livestock's Long Shadow", which received widespread international attention. It stated that livestock produced a staggering 18 percent of the world's greenhouse gas emissions. The agency drew a startling conclusion that livestock was doing more to harm the climate than all modes of transportation combined. This latter claim was wrong, and has since been corrected by Henning Steinfeld, the report's senior author.` },
    { id: 'cet6-2025-06-s3-mp-F', marker: 'F', text: `The problem was that analysts from the FAO used a comprehensive life-cycle assessment to study the climate impact of livestock, but a different method when they analyzed transportation. For livestock, they considered every factor associated with producing meat. This included emissions from fertilizer production, converting land from forests to pastures, growing feed, and direct emissions from animals (manure as well as expelling of gas from the stomach) from birth to death.` },
    { id: 'cet6-2025-06-s3-mp-G', marker: 'G', text: `However, when they looked at transportation's carbon footprint, they ignored impacts on the climate from manufacturing vehicle materials and parts, assembling vehicles and maintaining roads, bridges and airports. Instead, they only considered the exhaust smoke emitted by finished cars, trucks, trains and planes. As a result, the FAO's comparison of greenhouse gas emissions from livestock to those from transportation was greatly distorted.` },
    { id: 'cet6-2025-06-s3-mp-H', marker: 'H', text: `I pointed out this flaw during a speech to fellow scientists in San Francisco on March 22, 2010, which led to a flood of media coverage. To its credit, the FAO immediately owned up to its error. Unfortunately, the agency's initial claim that livestock was responsible for the lion's share of world greenhouse gas emissions had already received wide coverage. To this day, we struggle to "unring" the bell. In its most recent assessment report, the FAO estimated that livestock produces 14.5 percent of global greenhouse gas emissions from human activities. There is no comparable full life-cycle assessment for transportation. However, as Steinfeld has pointed out, direct emissions from transportation versus livestock can be compared and amount to 14 versus 5 percent, respectively.` },
    { id: 'cet6-2025-06-s3-mp-I', marker: 'I', text: `Many people continue to think that avoiding meat as infrequently as once a week will make a significant difference to the climate. But according to one recent study, even if Americans eliminated all animal protein from their diets, they would reduce greenhouse gas emissions by only 2.6 percent. According to our research at the University of California, Davis, if the practice of Meatless Monday were to be adopted by all Americans, we'd see a reduction of only 0.5 percent.` },
    { id: 'cet6-2025-06-s3-mp-J', marker: 'J', text: `Moreover, technological, genetic and management changes that have taken place in U.S. agriculture over the past 70 years have made livestock production more efficient and less greenhouse gas-intensive. According to the FAO's statistical database, total direct greenhouse gas emissions from U.S. livestock have declined by 11.3 percent since 1961, while production of livestock meat has more than doubled.` },
    { id: 'cet6-2025-06-s3-mp-K', marker: 'K', text: `Demand for meat is rising in developing and emerging economies, especially in the Middle East, North Africa and Southeast Asia. For example, raising livestock such as goats in Kenya is an important source of food and income for many small-scale farmers and herders. But meat consumption per person in these regions still lags that of developed countries. In 2015, average annual meat consumption per person in developed countries was 92 kilograms, compared to 24 kilograms in the Middle East and North Africa and 18 kilograms in Southeast Asia. Still, given projected population growth in the developing world, there will certainly be an opportunity for countries such as the United States to bring their sustainable livestock rearing practices to the table.` },
    { id: 'cet6-2025-06-s3-mp-L', marker: 'L', text: `Removing animals from U.S. agriculture would lower national greenhouse gas emissions to a small degree, but it would also make it harder to meet people's nutritional requirements. Many critics of animal agriculture are quick to point out that if farmers raised only plants, they could produce more pounds of food and more calories per person. But humans also need many essential micro- and macro-nutrients for good health. It's hard to make a compelling argument that the United States has a calorie deficit, given its high national rates of adult and child obesity. Moreover, not all plant parts are edible or desirable. Raising livestock is a way to add nutritional and economic value to plant agriculture.` },
    { id: 'cet6-2025-06-s3-mp-M', marker: 'M', text: `As one example, the energy in plants that livestock consume is most often contained in cellulose (纤维素), which is indigestible for humans and many other mammals. But cows, sheep and other ruminant (反刍的) animals can break cellulose down and release the solar energy contained in this vast resource. According to the FAO, as much as 70 percent of all agricultural land globally is range land that can only be utilized as grazing land for ruminant livestock.` },
    { id: 'cet6-2025-06-s3-mp-N', marker: 'N', text: `The world population is currently projected to reach 9.8 billion by 2050. Feeding this many people will raise immense challenges. Meat is more calorie-dense per serving than vegetarian options, and ruminant animals largely thrive on feed that is not suitable for humans. Raising livestock also offers much-needed income for small-scale farmers in developing nations. Worldwide, livestock provides a livelihood for 1 billion people.` },
    { id: 'cet6-2025-06-s3-mp-O', marker: 'O', text: `Climate change demands urgent attention, and the livestock industry has a large overall environmental footprint that affects air, water and land. These, combined with a rapidly rising world population, give us plenty of compelling reasons to continue to work for greater efficiencies in animal agriculture. I believe the place to start is with science-based facts.` },
  ],
};

